+++ b/clients/src/main/java/org/apache/kafka/common/utils/internals/Shell.java
@@ -93,7 +93,7 @@ public abstract class Shell {
             new InputStreamReader(process.getErrorStream(), StandardCharsets.UTF_8));
         BufferedReader inReader = new BufferedReader(
             new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8));
-        final StringBuffer errMsg = new StringBuffer();
+        final StringBuilder errMsg = new StringBuilder();

         // read error and input streams as this would free up the buffers
         // free the error stream buffer
@@ -180,7 +180,7 @@ public abstract class Shell {
     public static class ShellCommandExecutor extends Shell {

         private final String[] command;
-        private StringBuffer output;
+        private StringBuilder output;

         /**
          * Create a new instance of the ShellCommandExecutor to execute a command.
@@ -206,7 +206,7 @@ public abstract class Shell {
         }

         protected void parseExecResult(BufferedReader reader) throws IOException {
-            output = new StringBuffer();
+            output = new StringBuilder();
             char[] buf = new char[512];
             int nRead;
             while ((nRead = reader.read(buf, 0, buf.length)) > 0) {
